import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.BU4O3IzQ.js";const n="/penn-notes/news/2026-08/6f2679177f9a.jpg",i="/penn-notes/news/2026-08/1e265314a42a.jpg",o="/penn-notes/news/2026-08/b503a7500328.png",c="/penn-notes/news/2026-08/41568eb4095d.png",p="/penn-notes/news/2026-08/ddae3134988a.png",l="/penn-notes/news/2026-08/629e54341b22.jpg",d="/penn-notes/news/2026-08/0bb123cf2dc1.jpg",h="/penn-notes/news/2026-08/d6680c54d921.jpg",_=JSON.parse('{"title":"AI 动态 · 2026-08-10","description":"","frontmatter":{"title":"AI 动态 · 2026-08-10","date":"2026-08-10T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-10.md","filePath":"news/2026-08/ai-news-2026-08-10.md","lastUpdated":1787416107000}'),m={name:"news/2026-08/ai-news-2026-08-10.md"};function u(g,e,b,w,f,k){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-08-10" tabindex="-1">AI 动态 · 2026-08-10 <a class="header-anchor" href="#ai-动态-·-2026-08-10" aria-label="Permalink to &quot;AI 动态 · 2026-08-10&quot;">​</a></h1><blockquote><p>截至 2026-08-10。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="ai材料初创公司discovered-materials获900万美元融资-用ai寻找更高效芯片材料" tabindex="-1">AI材料初创公司Discovered Materials获900万美元融资，用AI寻找更高效芯片材料 <a class="header-anchor" href="#ai材料初创公司discovered-materials获900万美元融资-用ai寻找更高效芯片材料" aria-label="Permalink to &quot;AI材料初创公司Discovered Materials获900万美元融资，用AI寻找更高效芯片材料&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+n+'" alt="配图"></p><p>Discovered Materials宣布完成900万美元种子轮融资，资金将用于扩展AI驱动的材料发现平台，寻找可用于制造更高效芯片的新型材料。该公司利用AI模型预测和筛选具有优异热管理性能的材料，以应对芯片散热挑战。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/10/discovered-materials-is-playing-ai-whack-a-mole-to-hunt-cooler-chips/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="对冲基金situational-awareness向芯片初创source-foundry投资4亿美元" tabindex="-1">对冲基金Situational Awareness向芯片初创Source Foundry投资4亿美元 <a class="header-anchor" href="#对冲基金situational-awareness向芯片初创source-foundry投资4亿美元" aria-label="Permalink to &quot;对冲基金Situational Awareness向芯片初创Source Foundry投资4亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+i+'" alt="配图"></p><p>尽管近期遭遇挫折，AI对冲基金Situational Awareness仍向芯片初创公司Source Foundry投资4亿美元，押注新一代芯片技术。这笔投资显示该基金在经历困境后仍积极布局AI基础设施领域。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/09/embattled-hedge-fund-situational-awareness-invests-400m-in-chip-startup-source-foundry/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="hadrian融资13-7亿美元-打造ai驱动的国防工厂" tabindex="-1">Hadrian融资13.7亿美元，打造AI驱动的国防工厂 <a class="header-anchor" href="#hadrian融资13-7亿美元-打造ai驱动的国防工厂" aria-label="Permalink to &quot;Hadrian融资13.7亿美元，打造AI驱动的国防工厂&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">eciks.org</span><time datetime="2026-08-09">2026-08-09</time></p><p>Hadrian宣布完成13.7亿美元融资，用于建设AI驱动的国防制造工厂。该公司利用AI和自动化技术优化精密零部件生产流程，以满足国防工业对高精度、高效率制造的需求。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMibEFVX3lxTE8xWS1UV0htaF9BNzdBdUIzaTJXTUY3bVc1RlQ4OXhhTnB5MFdmc1dzZGJiV1dYTHp0eUl5Nkg0TXVFak5aYkJpWFd5STFvaEFHSjJ2SjJtRW14RnRpR3MyQlo1ZGJOQnVEdk5Heg?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ai推理规模上升后-华为重新定义-存储-的位置" tabindex="-1">AI推理规模上升后，华为重新定义“存储”的位置 <a class="header-anchor" href="#ai推理规模上升后-华为重新定义-存储-的位置" aria-label="Permalink to &quot;AI推理规模上升后，华为重新定义“存储”的位置&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+o+'" alt="配图"></p><p>华为在2026数据存储用户精英论坛上提出AI数据中心数据基础设施五层架构，强调当AI从训练进入大规模推理和Agent落地阶段，数据存储、管理和持续调用成为新瓶颈。华为认为AI发展重点正从算力、模型延伸到数据。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/qBHKWa0AabfP0Fs8rGrk?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="meta将开源其最强ai模型-对标openai和anthropic" tabindex="-1">Meta将开源其最强AI模型，对标OpenAI和Anthropic <a class="header-anchor" href="#meta将开源其最强ai模型-对标openai和anthropic" aria-label="Permalink to &quot;Meta将开源其最强AI模型，对标OpenAI和Anthropic&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CNBC</span><time datetime="2026-08-10">2026-08-10</time></p><p>Meta宣布将开源其最强大的AI模型，此举被视为对OpenAI和Anthropic等闭源竞争对手的直接挑战。Meta希望通过开源策略吸引开发者社区，推动AI技术普及，并建立更广泛的生态系统。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="meta发布muse-glimmer-本地、智能体、多模态且开源" tabindex="-1">Meta发布Muse Glimmer：本地、智能体、多模态且开源 <a class="header-anchor" href="#meta发布muse-glimmer-本地、智能体、多模态且开源" aria-label="Permalink to &quot;Meta发布Muse Glimmer：本地、智能体、多模态且开源&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+c+'" alt="配图"></p><p>Meta发布Muse Glimmer，一个本地运行的智能体多模态模型，并完全开源。该模型支持图像、文本和视频输入，旨在推动AI民主化，让开发者和研究者在本地设备上运行先进的AI功能。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/muse-glimmer" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="paperclip-开源智能体管理应用-用于管理工作中的ai代理" tabindex="-1">Paperclip：开源智能体管理应用，用于管理工作中的AI代理 <a class="header-anchor" href="#paperclip-开源智能体管理应用-用于管理工作中的ai代理" aria-label="Permalink to &quot;Paperclip：开源智能体管理应用，用于管理工作中的AI代理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">paperclipai/paperclip</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+p+'" alt="配图"></p><p>Paperclip是一个开源应用，旨在帮助团队管理工作中的AI代理。它提供统一的界面来管理、监控和协调多个智能体，提升团队协作效率，并支持自定义工作流。</p><p class="news-entry-source"><a href="https://github.com/paperclipai/paperclip" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="anthropic将claude-code自动模式设为默认-减少人工监督" tabindex="-1">Anthropic将Claude Code自动模式设为默认，减少人工监督 <a class="header-anchor" href="#anthropic将claude-code自动模式设为默认-减少人工监督" aria-label="Permalink to &quot;Anthropic将Claude Code自动模式设为默认，减少人工监督&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+l+'" alt="配图"></p><p>Anthropic宣布Claude Code的自动模式将默认启用，该模式允许AI自主执行更多编程任务，减少人工审批。此举旨在提升开发效率，但也引发了对代码质量和安全性的讨论。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/09/anthropic-is-turning-claude-codes-auto-mode-on-by-default/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="claude-code倒计时5天默认自动模式-额外token成本由anthropic承担" tabindex="-1">Claude Code倒计时5天默认自动模式，额外token成本由Anthropic承担 <a class="header-anchor" href="#claude-code倒计时5天默认自动模式-额外token成本由anthropic承担" aria-label="Permalink to &quot;Claude Code倒计时5天默认自动模式，额外token成本由Anthropic承担&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-10">2026-08-10</time></p><p>Anthropic宣布5天后Claude Code将默认启用自动模式，该模式下的分类器每次工具调用会额外消耗token，但成本由Anthropic承担。数据显示用户对权限请求的同意率高达97%，人工审批已流于形式。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/469500.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="动画化css-border-image-创造动态边框效果" tabindex="-1">动画化CSS border-image：创造动态边框效果 <a class="header-anchor" href="#动画化css-border-image-创造动态边框效果" aria-label="Permalink to &quot;动画化CSS border-image：创造动态边框效果&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+d+'" alt="配图"></p><p>CSS-Tricks文章探讨了如何动画化CSS border-image属性，利用border-image切片跨越整个边框的特性，结合动画创建引人注目的视觉效果。文章提供了示例和技巧，帮助开发者实现动态边框。</p><p class="news-entry-source"><a href="https://css-tricks.com/animating-css-border-image/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="smashingconf-freiburg-2026将于9月7-10日举行" tabindex="-1">SmashingConf Freiburg 2026将于9月7-10日举行 <a class="header-anchor" href="#smashingconf-freiburg-2026将于9月7-10日举行" aria-label="Permalink to &quot;SmashingConf Freiburg 2026将于9月7-10日举行&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-10">2026-08-10</time></p><p><img src="'+h+'" alt="配图"></p><p>Smashing Magazine宣布其线下会议SmashingConf Freiburg 2026将于9月7-10日在德国弗莱堡举行。会议为单轨制，邀请Jake Archibald、Hidde de Vries等知名前端开发者分享经验。</p><p class="news-entry-source"><a href="https://css-tricks.com/smashingconf-freiburg-2026-september-7-10/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const I=a(m,[["render",u]]);export{_ as __pageData,I as default};
